package GUI.components; import Program.model.Transaction; import javafx.beans.property.*; import javafx.collections.*; import javafx.scene.control.*; import java.time.format.DateTimeFormatter;
public class TransactionTable extends TableView<Transaction> {public TransactionTable(){setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_NEXT_COLUMN);TableColumn<Transaction,String> date=col("Date",t->t.getDate().toString()),type=col("Type",Transaction::getType),cat=col("Category",Transaction::getCategory),desc=col("Description",Transaction::getDescription),amount=col("Amount",t->String.format("%s৳%,.0f",t.getType().equals("Expense")?"- ":"+ ",t.getAmount()));getColumns().addAll(date,type,cat,desc,amount);} private TableColumn<Transaction,String> col(String n,java.util.function.Function<Transaction,String> f){TableColumn<Transaction,String> c=new TableColumn<>(n);c.setCellValueFactory(x->new SimpleStringProperty(f.apply(x.getValue())));return c;} public void setTransactions(java.util.List<Transaction> values){setItems(FXCollections.observableArrayList(values));}}
